namespace ZoneEngine.Core.Missions
{
    /// <summary>
    /// Captured "accepted mission" QuestFullUpdate packet (capture 20260717-pull-mish-doit, IN #8).
    /// Full transport packet (16-byte header + N3 body). The recipient identity and the mission expiry
    /// timestamp are patched before send; the leading MessageId is overwritten by the transport counter.
    /// </summary>
    internal static class MissionAcceptCaptureTemplate
    {
        /// <summary>Recipient character instance present in the recorded packet; replaced per recipient.</summary>
        public const int CapturedCharacterInstance = 0x0013945A;

        /// <summary>Raw big-endian byte offset of the mission expiry timestamp (Quest[0] action expiry).</summary>
        public const int ExpiryOffset = 671;

        /// <summary>
        /// QuestActionList outdoor marker block (Playfield2 type + instance + entrance ids + XYZ).
        /// Capture has Rome Blue pf 735 @ (720.6, 22.3, 301.6) — patched per rolled offer on send.
        /// </summary>
        public const int LocationPlayfieldTypeOffset = 687;

        public const int LocationPlayfieldInstanceOffset = 691;

        public const int LocationEntranceLowOffset = 695;

        public const int LocationEntranceHighOffset = 699;

        public const int LocationXOffset = 703;

        public const int LocationYOffset = 707;

        public const int LocationZOffset = 711;

        /// <summary>Full captured QuestFullUpdate packet (header + body) as hex.</summary>
        public const string CapturedPacketHex =
            "";
    }
}
